const wanted = (new URLSearchParams(location.search).get("lang") || navigator.language || "en").slice(0, 2).toLowerCase();
export const LANG = STRINGS[wanted] ? wanted : "en";
export const LOCALE = LANG === "pl" ? "pl-PL" : LANG === "de" ? "de-DE" : "en-GB";

export function t(key, vars = {}) {
  const s = STRINGS[LANG][key] ?? STRINGS.en[key] ?? key;
  return typeof s === "string" ? s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? "") : s;
}

// Static texts of the page: data-i18n (text / HTML), data-i18n-title (tooltip).
export function translatePage(root = document) {
  document.documentElement.lang = LANG;
  document.title = t("title");
  for (const el of root.querySelectorAll("[data-i18n]")) el.innerHTML = t(el.dataset.i18n);
  for (const el of root.querySelectorAll("[data-i18n-title]")) el.title = t(el.dataset.i18nTitle);
  const help = root.querySelector("#help-list");
  if (help) help.innerHTML = t("help").map((h) => `<li>${h}</li>`).join("");
}
